ALTER TABLE public.settings ADD COLUMN task_sale_mvg_per_five_usd numeric NOT NULL DEFAULT 0 CHECK(task_sale_mvg_per_five_usd BETWEEN 0 AND 1000000);
CREATE TABLE public.nft_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, description text NOT NULL, nft_id uuid NOT NULL REFERENCES public.nfts(id), award_quantity integer NOT NULL DEFAULT 1 CHECK(award_quantity BETWEEN 1 AND 100), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.nft_tasks TO authenticated; GRANT ALL ON public.nft_tasks TO service_role;
ALTER TABLE public.nft_tasks ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.nft_task_submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid NOT NULL REFERENCES public.nft_tasks(id), user_id uuid NOT NULL, evidence text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), review_note text, reviewed_by uuid, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(task_id,user_id));
GRANT SELECT ON public.nft_task_submissions TO authenticated; GRANT ALL ON public.nft_task_submissions TO service_role;
ALTER TABLE public.nft_task_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY submissions_read ON public.nft_task_submissions FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY tasks_read ON public.nft_tasks FOR SELECT TO authenticated USING(active OR public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.nft_task_submissions s WHERE s.task_id=nft_tasks.id AND s.user_id=auth.uid()));
CREATE TABLE public.task_nft_instances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nft_id uuid NOT NULL REFERENCES public.nfts(id), submission_id uuid NOT NULL REFERENCES public.nft_task_submissions(id), user_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.task_nft_instances TO authenticated; GRANT ALL ON public.task_nft_instances TO service_role;
ALTER TABLE public.task_nft_instances ENABLE ROW LEVEL SECURITY;
CREATE POLICY instances_read ON public.task_nft_instances FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.task_nft_listings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), instance_id uuid NOT NULL REFERENCES public.task_nft_instances(id), nft_id uuid NOT NULL REFERENCES public.nfts(id), seller_id uuid NOT NULL, buyer_id uuid, price_usd numeric NOT NULL CHECK(price_usd BETWEEN 0.01 AND 100000), status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','sold','cancelled')), created_at timestamptz NOT NULL DEFAULT now(), sold_at timestamptz);
GRANT SELECT ON public.task_nft_listings TO authenticated; GRANT ALL ON public.task_nft_listings TO service_role;
ALTER TABLE public.task_nft_listings ENABLE ROW LEVEL SECURITY;
CREATE POLICY task_listings_read ON public.task_nft_listings FOR SELECT TO authenticated USING(status='open' OR seller_id=auth.uid() OR buyer_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE UNIQUE INDEX task_instance_open_listing ON public.task_nft_listings(instance_id) WHERE status='open';
CREATE TABLE public.task_nft_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), listing_id uuid NOT NULL REFERENCES public.task_nft_listings(id), user_id uuid NOT NULL, seller_id uuid NOT NULL, reference text NOT NULL UNIQUE, amount_usd numeric NOT NULL, amount_ngn_kobo bigint NOT NULL, mining_mvg numeric NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','success','failed','needs_review')), expires_at timestamptz NOT NULL DEFAULT (now()+interval '30 minutes'), created_at timestamptz NOT NULL DEFAULT now(), verified_at timestamptz);
GRANT SELECT ON public.task_nft_orders TO authenticated; GRANT ALL ON public.task_nft_orders TO service_role;
ALTER TABLE public.task_nft_orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY task_orders_read ON public.task_nft_orders FOR SELECT TO authenticated USING(user_id=auth.uid() OR seller_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.crypto_nft_checkouts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL UNIQUE REFERENCES public.payments(id), user_id uuid NOT NULL, wallet_address text NOT NULL, amount_usdt numeric NOT NULL, tx_hash text UNIQUE, status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.crypto_nft_checkouts TO authenticated; GRANT ALL ON public.crypto_nft_checkouts TO service_role;
ALTER TABLE public.crypto_nft_checkouts ENABLE ROW LEVEL SECURITY;
CREATE POLICY crypto_checkout_read ON public.crypto_nft_checkouts FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));